INSERT INTO faqs (question, answer, sort_order) VALUES
  ('What time are your services?', 'Our service times are shown at the top of every page. Everyone is welcome.', 0),
  ('What should I wear?', 'Come as you are. You''ll see everything from casual to traditional and formal.', 1),
  ('Is there something for my children?', 'Yes. Children''s church runs during the main service with trained, caring volunteers.', 2),
  ('How do I become a member?', 'Talk to our welcome team after service or send us a message, and we''ll tell you about our membership class.', 3),
  ('Is my prayer request private?', 'Yes. Prayer requests are only shared with our pastoral and prayer team.', 4);
